/**
 * External id generation (§8.1).
 *
 *  - runs:      `run_` + 26 chars of Crockford base32 (a ULID)
 *  - sandboxes: `sbx_` + 16 chars
 *
 * Ids are generated by the server, are the only ids that cross the wire, and
 * encode nothing about the database.
 */

import { createHash, randomBytes } from 'node:crypto';

const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

function encodeCrockford(value: number, length: number): string {
  let remaining = Math.max(0, Math.trunc(value));
  let output = '';
  for (let index = 0; index < length; index += 1) {
    output = (CROCKFORD[remaining % 32] ?? '0') + output;
    remaining = Math.floor(remaining / 32);
  }
  return output;
}

function randomCrockford(length: number): string {
  const bytes = randomBytes(length);
  let output = '';
  for (let index = 0; index < length; index += 1) {
    output += CROCKFORD[(bytes[index] ?? 0) % 32] ?? '0';
  }
  return output;
}

/** `run_` + a 26-character ULID: 48-bit time, 80 bits of randomness. */
export function newRunId(now: number = Date.now()): string {
  return `run_${encodeCrockford(now, 10)}${randomCrockford(16)}`;
}

/** `sbx_` + 16 characters. */
export function newSandboxId(): string {
  return `sbx_${randomCrockford(16)}`;
}

/** 32 random bytes, hex-encoded. Used for the per-run broker token and never stored. */
export function newBrokerToken(): string {
  return randomBytes(32).toString('hex');
}

/** `ses_` + 26 characters. */
export function newSessionId(): string {
  return `ses_${randomCrockford(26)}`;
}

/** `msg_` + 26 characters. */
export function newMessageId(): string {
  return `msg_${randomCrockford(26)}`;
}

export function sha256Hex(value: string | Buffer): string {
  return createHash('sha256').update(value).digest('hex');
}

/** The event digest in the report's evidence section (§6.3). */
export function digestJson(value: unknown): string {
  return `sha256:${sha256Hex(JSON.stringify(value))}`;
}
